  drivetrain: () => 'Cranks · drag round to pedal',
  saddle: (b) => `Saddle height · size ${sizeOf(b).name}`,
  cockpit: (b) => `Handlebar · ${barOf(b).name}`,
  fenders: () => 'Full-length fenders',
  rack: () => 'Rear rack',
  lights: () => 'Dynamo lights · spin the front wheel',
};

export function BikeDrawing({ build, fit, uid, reduced, drive, shownPaint, flow, onFlowEnd, hover, onHover, onPick, children }: DrawingProps) {
  const s = solve(fit);
  const svg = useRef<SVGSVGElement>(null);
  const flowRef = useRef<SVGGElement>(null);
  const titanium = frameOf(build).id === 'titanium';
  const paint = paintOf(build);
  const tyre = tyreOf(build);
  const has = (e: ExtraId) => build.extras.includes(e);
  const frameColour = titanium ? 'var(--hc-ti)' : shownPaint;
  const lightPaint = titanium || paint.id === 'chalk' || paint.id === 'marigold';

  const tubes = [
    { k: 'ht', a: along(s.htTop, s.down, -8), b: along(s.htBot, s.down, 6), d: 36 },
    { k: 'tt', a: s.ttFront, b: s.seatCluster, d: 28.6 },
    { k: 'dt', a: s.dtFront, b: s.bb, d: 31.8 },
    { k: 'st', a: s.stTop, b: s.bb, d: 28.6 },
    { k: 'ss', a: s.ssTop, b: s.rear, d: 16 },
    { k: 'cs', a: s.bb, b: s.rear, d: 19 },
  ];
  const fork = `M${P(s.crown)}Q${P(s.forkCtrl)} ${P(s.front)}`;
  const crown = seg(s.htBot, along(s.htBot, s.down, 24));

  // Drivetrain (chainring and crank are drawn around their own origin, then placed at the bottom bracket).
  const ringR = 89, cogR = 40;
  const upper = tangent(s.bb, ringR, s.rear, cogR, -1);
  const jockeyHi = off(s.rear, 8, -44), jockeyLo = off(s.rear, 22, -92);
  const lower = tangent(s.bb, ringR, jockeyLo, 13, 1);
  const crankEnd = onCircle(O, 170, -38);
  const chainD = `${seg(upper[0], upper[1])}${seg(lower[0], lower[1])}${seg(off(jockeyLo, -13, 0), off(jockeyHi, -13, 0))}${seg(off(jockeyHi, 13, 0), onCircle(s.rear, cogR, 290))}`;
  drive.chainLen.current = Math.hypot(upper[1].x - upper[0].x, upper[1].y - upper[0].y) + Math.hypot(lower[1].x - lower[0].x, lower[1].y - lower[0].y) + 48 + 60;

  // Fitted extras
  const fenderR = s.radius + 14;
  const platY = s.rear.y + s.radius + 52;
  const rackRear = pt(s.rear.x - 140, platY), rackFront = pt(s.rear.x + 132, platY);
  const t = Math.min(0.98, Math.max(0, (platY + 14 - s.rear.y) / (s.ssTop.y - s.rear.y)));
  const rackAttach = lerp(s.rear, s.ssTop, t);
  const eyelet = off(s.rear, -18, 26);
  const headlight = along(along(s.htBot, s.down, 26), s.perp, 46);
  const tail = has('rack') ? off(rackRear, -6, -26) : has('fenders') ? onCircle(s.rear, fenderR + 4, 168) : along(s.bb, s.stDir, fit.st + 60);
  const beam = `M${P(off(headlight, 30, 10))}L${P(off(headlight, 300, 70))}L${P(off(headlight, 300, -95))}L${P(off(headlight, 30, -10))}Z`;

  // Dimension lines (labels are HTML, laid over the drawing)
  const wbY = s.ground - 70;
  const dtAngle = (Math.atan2(s.dtFront.y - s.bb.y, s.dtFront.x - s.bb.x) * 180) / Math.PI;
  const decal = lerp(s.bb, s.dtFront, 0.56);

  // Paint flows down the tubes from the head tube when the colour changes.
  useIsomorphicLayoutEffect(() => {
    const g = flowRef.current;
    if (!flow || !g) return;
    if (reduced) { onFlowEnd(); return; }
    const paths = [...g.querySelectorAll<SVGPathElement>('path')];
    const seq = createSequence();
    paths.forEach((p, i) => seq.add(p, [{ strokeDashoffset: 1 }, { strokeDashoffset: 0 }], { at: i * 70, duration: 420, easing: 'inOut' }));
    void seq.play().then((done) => { if (done) onFlowEnd(); });
    return () => seq.cancel();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [flow?.key]);

  // Pen-and-ink entrance: outlines draw themselves, then the paint and parts arrive.
  useEffect(() => {
    const el = svg.current;
    if (reduced || !el) return;
    const seq = createSequence()
      .add(el.querySelectorAll('[data-ink]'), [{ strokeDasharray: '1 1', strokeDashoffset: 1 }, { strokeDasharray: '1 1', strokeDashoffset: 0 }], { duration: 620, stagger: 26, easing: 'inOut', fill: 'backwards' })
      .add(el.querySelectorAll('[data-wash]'), [{ opacity: 0 }, { opacity: 1 }], { at: 360, duration: 360, stagger: 60, easing: 'standard', fill: 'backwards' });
    void seq.play();
    return () => seq.cancel();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  const centreOf = (p: Pt) => {
    const m = svg.current?.getScreenCTM();
    if (!m) return { x: 0, y: 0 };
    return { x: m.a * p.x + m.c * -p.y + m.e, y: m.b * p.x + m.d * -p.y + m.f };
  };
  const pressed = useRef<{ part: PartId; spin: Spin | null } | null>(null);
  const down = (part: PartId, spin: Spin | null, axle?: Pt) => (e: RPointerEvent<SVGGElement>) => {
    if (e.button !== 0) return;
    pressed.current = { part, spin };
    if (spin && axle && drive.grab(spin, e, centreOf(axle))) svg.current?.setPointerCapture(e.pointerId);
  };
  const onMove = (e: RPointerEvent<SVGSVGElement>) => { drive.move(e); };
  const onUp = (e: RPointerEvent<SVGSVGElement>) => {
    const turned = drive.release(e);
    const p = pressed.current;
    pressed.current = null;
    // A press that did not turn anything is a click: it opens the option group that changes this part.
    if (p && turned < 4 && e.type === 'pointerup') onPick(p.part);
  };
  const hoverProps = (part: PartId) => ({
    'data-part': part,
    'data-hover': hover === part || undefined,
    onPointerEnter: (e: RPointerEvent<SVGGElement>) => { if (e.pointerType !== 'touch') onHover(part); },
    onPointerLeave: () => { if (!drive.dragging()) onHover(null); },
  });


  return (
    <div className={styles.drawing} data-hovering={hover ?? undefined}>
      <svg ref={svg} className={styles.svg} viewBox={`${VIEW.minX} ${-VIEW.maxY} ${VIEW_W} ${VIEW_H}`} role="img" aria-labelledby={`${uid}-dt ${uid}-dd`} preserveAspectRatio="xMidYMid meet"
        onPointerMove={onMove} onPointerUp={onUp} onPointerCancel={onUp} onLostPointerCapture={(e) => drive.release(e)}>
        <title id={`${uid}-dt`}>Side elevation of the Hollin Drover</title>
        <desc id={`${uid}-dd`}>{`${describeBuild(build)} Stack ${mm(fit.stack)} mm, reach ${mm(fit.reach)} mm, wheelbase ${mm(s.wheelbase)} mm.`}</desc>
        <defs>
          <linearGradient id={`${uid}-beam`} x1="0" x2="1" y1="0" y2="0">
            <stop offset="0" stopColor="var(--hc-beam)" stopOpacity="0.85" />
            <stop offset="1" stopColor="var(--hc-beam)" stopOpacity="0" />
          </linearGradient>
          <radialGradient id={`${uid}-glow`}>
            <stop offset="0" stopColor="var(--hc-tail)" stopOpacity="0.75" />
            <stop offset="1" stopColor="var(--hc-tail)" stopOpacity="0" />
          </radialGradient>
        </defs>

        <path d={seg(pt(VIEW.minX + 40, s.ground), pt(VIEW.maxX - 40, s.ground))} className={styles.ground} />

        <g className={styles.hit} {...hoverProps('wheels')}>
          {([['rear', s.rear], ['front', s.front]] as const).map(([k, c]) => (
            <g key={k} className={styles.wheel} onPointerDown={down('wheels', k, c)}>
              <g transform={`translate(${c.x.toFixed(1)} ${(-c.y).toFixed(1)})`}>
                <circle r={s.radius - fit.tyre / 2} strokeWidth={fit.tyre} className={styles.tyre} />
                <g ref={(el) => { drive.groups.current[k] = el; }}>
                  <circle r={RIM_R - 7} strokeWidth={14} className={styles.rim} pathLength={1} data-ink="" />
                  <path d={spokes(O, k === 'front' && has('lights') ? 26 : 18, RIM_R - 14)} className={styles.spokes} />
                  <circle r={s.radius - fit.tyre * 0.68} strokeWidth={fit.tyre * 0.5} className={`${styles.part} ${styles.tan}`} data-on={tyre.tan} />
                  <circle r={s.radius - 3} strokeWidth={10} strokeDasharray="11 9" className={`${styles.part} ${styles.knobs}`} data-on={tyre.id === 'gravel45'} />
                  <rect x={-5} y={-(RIM_R + 4)} width={10} height={22} rx={3} className={styles.valve} />
                </g>
                <circle r={k === 'front' && has('lights') ? 30 : k === 'rear' ? 22 : 17} className={styles.hub} />
                <circle r={s.radius + 1} className={styles.edge} pathLength={1} data-ink="" />
                <circle r={s.radius - fit.tyre - 1} className={styles.edge} />
              </g>
            </g>
          ))}
        </g>

        <g className={`${styles.part} ${styles.lift} ${styles.hit}`} data-on={has('fenders')} {...hoverProps('fenders')} onPointerDown={down('fenders', null)}>
          <path d={arc(s.front, fenderR, 208, 18)} strokeWidth={17} className={styles.outline} />
          <path d={arc(s.rear, fenderR, 172, 4)} strokeWidth={17} className={styles.outline} />
          <path d={arc(s.front, fenderR, 208, 18)} strokeWidth={11} className={styles.alloy} />
          <path d={arc(s.rear, fenderR, 172, 4)} strokeWidth={11} className={styles.alloy} />
          <path d={seg(onCircle(s.front, fenderR, 208), onCircle(s.front, fenderR + 70, 214))} strokeWidth={9} className={styles.rubber} />
          <path d={`${seg(onCircle(s.front, fenderR - 4, 200), s.front)}${seg(onCircle(s.rear, fenderR - 4, 160), s.rear)}`} className={styles.stay} />
        </g>

        <g className={`${styles.part} ${styles.lift} ${styles.hit}`} data-on={has('rack')} {...hoverProps('rack')} onPointerDown={down('rack', null)}>
          <path d={`${seg(rackRear, rackFront)}${seg(off(rackRear, 20, 0), eyelet)}${seg(off(rackRear, 170, 0), eyelet)}${seg(rackFront, rackAttach)}`} strokeWidth={11} className={styles.rack} />
        </g>

        <g className={styles.hit} {...hoverProps('saddle')} onPointerDown={down('saddle', null)}>
          <path d={seg(along(s.bb, s.stDir, fit.st - 40), s.postTop)} strokeWidth={27} className={styles.metalOutlined} />
          <path d={`M${P(off(s.saddle, -150, -18))}C${P(off(s.saddle, -152, 2))} ${P(off(s.saddle, -110, 6))} ${P(off(s.saddle, -40, 2))}L${P(off(s.saddle, 110, -6))}C${P(off(s.saddle, 122, -8))} ${P(off(s.saddle, 124, -20))} ${P(off(s.saddle, 112, -24))}L${P(off(s.saddle, -30, -30))}C${P(off(s.saddle, -100, -36))} ${P(off(s.saddle, -148, -36))} ${P(off(s.saddle, -150, -18))}Z`} className={styles.saddle} />
          <path d={seg(off(s.saddle, -70, -40), off(s.saddle, 70, -36))} strokeWidth={7} className={styles.alloy} />
        </g>

        <g className={styles.hit} {...hoverProps('frame')} onPointerDown={down('frame', null)}>
          {tubes.map((tb) => <path key={tb.k} d={seg(tb.a, tb.b)} strokeWidth={tb.d + 7} className={styles.outline} pathLength={1} data-ink="" />)}
          <path d={fork} strokeWidth={29} className={styles.outline} pathLength={1} data-ink="" />
          <path d={crown} strokeWidth={47} className={styles.outline} />
          <circle cx={s.bb.x} cy={-s.bb.y} r={26.5} className={styles.outlineFill} />
          <circle cx={s.rear.x} cy={-s.rear.y} r={18.5} className={styles.outlineFill} />

          <g data-wash="">
            {tubes.map((tb) => <path key={tb.k} d={seg(tb.a, tb.b)} strokeWidth={tb.d} className={styles.paint} style={{ stroke: frameColour }} />)}
            <circle cx={s.bb.x} cy={-s.bb.y} r={23} className={styles.paintFill} style={{ fill: frameColour }} />
            <circle cx={s.rear.x} cy={-s.rear.y} r={15} className={styles.paintFill} style={{ fill: frameColour }} />
            <path d={fork} strokeWidth={22} className={styles.paint} style={{ stroke: shownPaint }} />
            <path d={crown} strokeWidth={40} className={styles.paint} style={{ stroke: shownPaint }} />
            <circle cx={s.front.x} cy={-s.front.y} r={14} className={styles.paintFill} style={{ fill: shownPaint }} />
          </g>
          {flow ? (
            <g ref={flowRef} key={flow.key} className={styles.flow} aria-hidden="true">
              <path d={crown} strokeWidth={40} pathLength={1} style={{ stroke: flow.colour }} />
              {(titanium ? [] : tubes).map((tb) => <path key={tb.k} d={seg(tb.a, tb.b)} strokeWidth={tb.d} pathLength={1} style={{ stroke: flow.colour }} />)}
              <path d={fork} strokeWidth={22} pathLength={1} style={{ stroke: flow.colour }} />
            </g>
          ) : null}

          <g className={styles.part} data-on={titanium}>
            {tubes.filter((tb) => tb.k !== 'ht').map((tb) => {
              const n = (() => { const dx = tb.b.x - tb.a.x, dy = tb.b.y - tb.a.y, l = Math.hypot(dx, dy) || 1; return pt(-dy / l, dx / l); })();
              const k = tb.d * 0.22;
              return <path key={tb.k} d={seg(lerp(along(tb.a, n, k), along(tb.b, n, k), 0.08), lerp(along(tb.a, n, k), along(tb.b, n, k), 0.92))} strokeWidth={tb.d * 0.14} className={styles.tiShine} />;
            })}
          </g>

          <circle cx={along(lerp(s.htTop, s.htBot, 0.4), s.perp, 19).x} cy={-along(lerp(s.htTop, s.htBot, 0.4), s.perp, 19).y} r={9} className={styles.badge} />
          <text className={styles.decal} data-light={lightPaint} transform={`translate(${decal.x.toFixed(1)} ${(-decal.y).toFixed(1)}) rotate(${(-dtAngle).toFixed(2)})`}>HOLLIN</text>
        </g>

        <g className={`${styles.hit} ${styles.spin}`} {...hoverProps('drivetrain')} onPointerDown={down('drivetrain', 'crank', s.bb)}>
          <path d={chainD} className={styles.chain} strokeWidth={8} pathLength={100} strokeDasharray="0.9 0.6" ref={(el) => { drive.groups.current.chain = el; }} />
          <path d={seg(off(s.rear, 6, -10), jockeyLo)} strokeWidth={14} className={styles.mech} />
          <circle cx={jockeyHi.x} cy={-jockeyHi.y} r={13} className={styles.jockey} />
          <circle cx={jockeyLo.x} cy={-jockeyLo.y} r={13} className={styles.jockey} />
          <circle cx={s.rear.x} cy={-s.rear.y} r={cogR} strokeWidth={7} className={styles.cog} />
          <g transform={`translate(${s.bb.x.toFixed(1)} ${(-s.bb.y).toFixed(1)})`}>
            <g ref={(el) => { drive.groups.current.crank = el; }}>
              <circle r={ringR} strokeWidth={12} className={styles.ring} />
              <circle r={ringR + 7} strokeWidth={7} strokeDasharray="5 5" className={styles.ring} />
              <path d={seg(O, crankEnd)} strokeWidth={30} className={styles.outline} />
              <path d={seg(O, crankEnd)} strokeWidth={23} className={styles.crank} />
              <g transform={`translate(${crankEnd.x.toFixed(1)} ${(-crankEnd.y).toFixed(1)})`}>
                <g ref={(el) => { drive.groups.current.pedal = el; }}>
                  <path d={seg(pt(-44, -6), pt(44, -6))} strokeWidth={22} className={styles.rubber} />
                </g>
              </g>
            </g>
            <circle r={14} className={styles.hub} />
          </g>
        </g>

        <g className={styles.hit} {...hoverProps('cockpit')} onPointerDown={down('cockpit', null)}>
          <path d={seg(along(s.htTop, s.down, -2), along(s.htTop, s.down, -40))} strokeWidth={30} className={styles.metalOutlined} />
          <path d={seg(s.steererTop, s.clamp)} strokeWidth={34} className={styles.outline} />
          <path d={seg(s.steererTop, s.clamp)} strokeWidth={28} className={styles.stem} />
          {BARS.map((id) => (
            <g key={id} className={`${styles.part} ${styles.drop}`} data-on={build.bar === id}>
              {barStrokes(id, s.clamp).map((st, i) => <path key={`o${i}`} d={st.d} strokeWidth={st.w + 7} className={styles.outline} />)}
              {barStrokes(id, s.clamp).map((st, i) => <path key={`f${i}`} d={st.d} strokeWidth={st.w} className={st.tone === 'tape' ? styles.tape : styles.alloy} />)}
            </g>
          ))}
        </g>

        <g className={`${styles.part} ${styles.lift} ${styles.hit}`} data-on={has('lights')} {...hoverProps('lights')} onPointerDown={down('lights', null)}>
          <path d={beam} fill={`url(#${uid}-beam)`} className={styles.beam} />
          <circle cx={tail.x - 10} cy={-tail.y} r={70} fill={`url(#${uid}-glow)`} className={styles.beam} />
          <path d={`M${P(off(s.front, -8, 28))}Q${P(off(s.forkCtrl, -16, 0))} ${P(along(s.crown, s.perp, 14))}`} className={styles.wire} />
          <path d={seg(along(s.htBot, s.down, 22), headlight)} strokeWidth={8} className={styles.alloy} />
          <rect x={headlight.x - 26} y={-headlight.y - 15} width={52} height={30} rx={9} className={styles.lamp} />
          <circle cx={headlight.x + 22} cy={-headlight.y} r={11} className={styles.lens} />
          <rect x={tail.x - 13} y={-tail.y - 20} width={26} height={40} rx={7} className={styles.tail} />
        </g>

        <g className={styles.dimLines} data-wash="">
          <path d={`${seg(off(s.rear, 0, -s.radius - 14), pt(s.rear.x, wbY - 18))}${seg(off(s.front, 0, -s.radius - 14), pt(s.front.x, wbY - 18))}`} className={styles.ext} />
          <path d={`${seg(pt(s.rear.x, wbY), pt(s.front.x, wbY))}${seg(pt(s.rear.x, wbY - 14), pt(s.rear.x, wbY + 14))}${seg(pt(s.front.x, wbY - 14), pt(s.front.x, wbY + 14))}`} className={styles.dim} />
          <path d={`${seg(pt(s.htTop.x, 0), pt(s.htTop.x, s.htTop.y))}${seg(pt(s.htTop.x - 14, 0), pt(s.htTop.x + 14, 0))}${seg(pt(0, s.htTop.y), pt(s.htTop.x, s.htTop.y))}${seg(pt(0, s.htTop.y - 14), pt(0, s.htTop.y + 14))}`} className={styles.dim} />
          <path d={seg(pt(0, 0), pt(0, s.htTop.y - 14))} className={styles.ext} />
        </g>
      </svg>

      <div className={styles.dims} aria-hidden="true">
        <span className={styles.dimLabel} data-align="start" style={toPct(pt(s.htTop.x + 22, s.htTop.y * 0.5))}>Stack <b>{mm(fit.stack)}</b></span>
        <span className={styles.dimLabel} data-align="center" style={toPct(pt(s.htTop.x * 0.5, s.htTop.y + 40))}>Reach <b>{mm(fit.reach)}</b></span>
        <span className={styles.dimLabel} data-align="center" style={toPct(pt((s.rear.x + s.front.x) / 2, wbY - 44))}>Wheelbase <b>{mm(s.wheelbase)}</b></span>
        {hover ? <span key={hover} className={styles.partTag}>{LABEL[hover](build)}</span> : null}
      </div>
      {children}
    </div>
  );
}

/* Hollin Drover — a frame builder's drawing table.
   Ink linework on drafting paper, dimension lines in the signal colour, mono labels, one heavy grotesque for the
   model name. Paint colours are product content; every UI colour comes from the theme tokens. */

.root {
  --hc-line: var(--mk-ink, #11110f);
  --hc-metal: #a5a7a2;
  --hc-spoke: #767873;
  --hc-rubber: #242421;
  --hc-tan: #c4955a;
  --hc-ti: #b9bab4;
  --hc-ti-hi: #f1f1ec;
  --hc-brass: #b98a35;
  --hc-lens: #f4ead0;
  --hc-tail: #c4361f;
  --hc-beam: #f0b93a;
  /* Two-layer elevation (contact + ambient), light from the top-left. */
  --sh-rest: 0 1px 1.5px rgb(20 18 12 / 0.16), 0 6px 14px -9px rgb(20 18 12 / 0.3);
  --sh-lift: 0 1px 1px rgb(20 18 12 / 0.12), 0 16px 28px -14px rgb(20 18 12 / 0.36);
  --sh-press: 0 0 0 rgb(0 0 0 / 0), 0 2px 4px -2px rgb(20 18 12 / 0.3);
  --hc-grid: color-mix(in oklab, var(--mk-ink, #11110f) 6%, transparent);
  --plate-h: calc((100cqi - 32px) / 1.603 + 92px);
  background: var(--mk-bg, #f3f0e8);
  color: var(--mk-ink, #11110f);
  font-family: var(--mk-font-text, ui-sans-serif, system-ui, sans-serif);
  overflow-x: clip;
}
:global([data-theme='dark']) .root {
  --sh-rest: 0 1px 1.5px rgb(0 0 0 / 0.5), 0 6px 14px -9px rgb(0 0 0 / 0.75);
  --sh-lift: 0 1px 1px rgb(0 0 0 / 0.45), 0 18px 30px -14px rgb(0 0 0 / 0.85);
  --sh-press: 0 0 0 rgb(0 0 0 / 0), 0 2px 4px -2px rgb(0 0 0 / 0.7);
  --hc-metal: #92948f;
  --hc-spoke: #8d8f8a;
  --hc-rubber: #3b3a36;
  --hc-ti: #a9aaa4;
  --hc-ti-hi: #e3e4de;
}

.srOnly {
  position: absolute; width: 1px; height: 1px; margin: -1px; padding: 0; overflow: hidden; clip: rect(0 0 0 0); white-space: nowrap; border: 0;
}

/* ── Layout: plate (sticky) + intro + options ─────────────────────────── */
.layout {
  display: grid;
  grid-template-columns: minmax(0, 1fr);
  grid-template-areas: 'intro' 'plate' 'options';
  column-gap: clamp(28px, 4cqi, 72px);
  max-width: 1520px;
  margin-inline: auto;
  padding-inline: 16px;
}
.intro { grid-area: intro; padding-block: 28px 18px; }
.plate {
  grid-area: plate;
  position: sticky;
  top: 44px;
  z-index: 3;
  align-self: start;
  margin-inline: -16px;
  padding: 6px 16px 10px;
  background: var(--mk-bg, #f3f0e8);
  border-block: 1px solid var(--mk-line, #11110f24);
}
.options { grid-area: options; padding-bottom: 32px; }

@container (min-width: 960px) {
  .layout { grid-template-columns: minmax(0, 1.62fr) minmax(360px, 1fr); grid-template-areas: 'plate intro' 'plate options'; grid-template-rows: auto 1fr; padding-inline: 32px; }
  .intro { padding-block: 40px 12px; }
  .plate {
    margin-inline: 0;
    padding: 20px 0 24px;
    border-block: 0;
    height: calc(100dvh - 44px);
    max-height: 980px;
    display: flex;
    flex-direction: column;
  }
}

/* ── Intro ─────────────────────────────────────────────────────────────── */
.brand { display: flex; align-items: center; justify-content: space-between; gap: 12px; margin: 0; }
.wordmark { font-family: var(--mk-font-mono, ui-monospace, monospace); font-size: 0.75rem; letter-spacing: 0.14em; text-transform: uppercase; }
.tag {
  font-family: var(--mk-font-mono, ui-monospace, monospace); font-size: 0.6875rem; letter-spacing: 0.08em; text-transform: uppercase;
  border: 1px solid var(--mk-line-strong, #11110f); border-radius: 999px; padding: 3px 9px;
}
.model {
  margin: 14px 0 0;
  font-family: var(--mk-font-display, ui-sans-serif, system-ui, sans-serif);
  font-weight: 800;
  font-size: clamp(4rem, 1.5rem + 11cqi, 7.25rem);
  line-height: 0.8;
  letter-spacing: -0.065em;
  margin-left: -0.04em;
}
.lede { margin: 18px 0 0; max-width: 40ch; font-size: 1rem; line-height: 1.5; color: var(--mk-ink-muted, #5c5a52); text-wrap: pretty; }

/* ── Plate: the drawing ────────────────────────────────────────────────── */
.plateHead { display: none; }
.plateTitle, .code {
  margin: 0; font-family: var(--mk-font-mono, ui-monospace, monospace); font-size: 0.75rem; font-weight: 400; letter-spacing: 0.08em; text-transform: uppercase;
}
.code { letter-spacing: 0.04em; font-variant-numeric: tabular-nums; color: var(--mk-ink-muted, #5c5a52); }
.drawingWrap { display: grid; place-items: center; min-height: 0; }
.drawing {
  position: relative;
  width: 100%;
  aspect-ratio: 1940 / 1210;
  background-color: var(--mk-surface, #fbf9f4);
  background-image:
    linear-gradient(var(--hc-grid) 1px, transparent 1px),
    linear-gradient(90deg, var(--hc-grid) 1px, transparent 1px);
  background-size: 24px 24px;
  background-position: -1px -1px;
  border: 1px solid var(--mk-line, #11110f24);
  border-radius: var(--mk-radius-s, 4px);
}
.svg { position: absolute; inset: 0; width: 100%; height: 100%; overflow: visible; }
.caption { display: none; }

@container (min-width: 960px) {
  .plateHead { display: flex; justify-content: space-between; gap: 16px; padding-bottom: 12px; border-bottom: 1px solid var(--mk-line, #11110f24); margin-bottom: 16px; }
  .drawingWrap { flex: 1 1 auto; }
  .drawing { width: min(100%, calc((min(100dvh, 980px) - 44px - 250px) * 1.603)); }
  .caption { display: block; margin: 14px 0 0; max-width: 72ch; font-size: 0.875rem; line-height: 1.5; color: var(--mk-ink-muted, #5c5a52); }
}

/* SVG parts */
.ground { stroke: var(--mk-ink-muted, #5c5a52); stroke-width: 1; stroke-dasharray: 2 5; fill: none; vector-effect: non-scaling-stroke; }
.rim { fill: none; stroke: var(--hc-metal); }
.spokes { fill: none; stroke: var(--hc-spoke); stroke-width: 0.8; vector-effect: non-scaling-stroke; }
.hub { fill: var(--hc-metal); stroke: var(--hc-line); stroke-width: 1; vector-effect: non-scaling-stroke; }
.tyre { fill: none; stroke: var(--hc-rubber); }
.tan { fill: none; stroke: var(--hc-tan); }
.knobs { fill: none; stroke: var(--hc-rubber); }
.edge { fill: none; stroke: var(--hc-line); stroke-width: 1.1; vector-effect: non-scaling-stroke; }
.outline { fill: none; stroke: var(--hc-line); stroke-linecap: round; stroke-linejoin: round; }
.outlineFill { fill: var(--hc-line); }
.paint { fill: none; stroke-linecap: round; stroke-linejoin: round; }
.paintFill { stroke: none; }
.tiShine { fill: none; stroke: var(--hc-ti-hi); stroke-linecap: round; }
.badge { fill: var(--hc-brass); stroke: var(--hc-line); stroke-width: 1; vector-effect: non-scaling-stroke; }
.decal {
  font-family: var(--mk-font-mono, ui-monospace, monospace); font-size: 30px; font-weight: 700; letter-spacing: 0.32em;
  text-anchor: middle; dominant-baseline: central; fill: #f6f3ea;
}
.decal[data-light='true'] { fill: #1d1d1a; }
.alloy { fill: none; stroke: var(--hc-metal); stroke-linecap: round; stroke-linejoin: round; }
.metalOutlined { fill: none; stroke: var(--hc-metal); stroke-linecap: round; paint-order: stroke; }
.rubber { fill: none; stroke: var(--hc-rubber); stroke-linecap: round; }
.stay { fill: none; stroke: var(--hc-metal); stroke-width: 1.4; vector-effect: non-scaling-stroke; }
.rack { fill: none; stroke: var(--hc-rubber); stroke-linecap: round; stroke-linejoin: round; }
.chain { fill: none; stroke: var(--hc-spoke); stroke-linecap: round; }
.mech { fill: none; stroke: var(--hc-rubber); stroke-linecap: round; }
.jockey { fill: var(--hc-rubber); stroke: var(--hc-metal); stroke-width: 1; vector-effect: non-scaling-stroke; }
.cog { fill: none; stroke: var(--hc-metal); }
.ring { fill: none; stroke: var(--hc-metal); }
.crank { fill: none; stroke: var(--hc-metal); stroke-linecap: round; }
.saddle { fill: var(--hc-rubber); stroke: var(--hc-line); stroke-width: 1; vector-effect: non-scaling-stroke; }
.stem { fill: none; stroke: var(--hc-metal); stroke-linecap: round; }
.tape { fill: none; stroke: var(--hc-rubber); stroke-linecap: round; stroke-linejoin: round; }
.wire { fill: none; stroke: var(--hc-rubber); stroke-width: 1.4; vector-effect: non-scaling-stroke; }
.lamp { fill: var(--hc-rubber); stroke: var(--hc-line); stroke-width: 1; vector-effect: non-scaling-stroke; }
.lens { fill: var(--hc-lens); stroke: var(--hc-line); stroke-width: 1; vector-effect: non-scaling-stroke; }
.tail { fill: var(--hc-tail); stroke: var(--hc-line); stroke-width: 1; vector-effect: non-scaling-stroke; }
.dimLines { pointer-events: none; }
.dim { fill: none; stroke: var(--mk-signal, #bf2f09); stroke-width: 1; vector-effect: non-scaling-stroke; }
.ext { fill: none; stroke: var(--mk-signal, #bf2f09); stroke-width: 1; stroke-dasharray: 3 4; vector-effect: non-scaling-stroke; }

/* Every variant is drawn; the chosen one is opaque. Parts and bars drop in on a spring, the old one lifts away. */
.part { opacity: 0; }
.part[data-on='true'] { opacity: 1; }
.part[data-on='false'] { pointer-events: none; }
.lift { transform: translateY(-40px); }
.lift[data-on='true'] { transform: none; }
.drop { transform: translateY(-34px) rotate(-4deg); transform-box: fill-box; transform-origin: 0% 50%; }
.drop[data-on='true'] { transform: none; }
@media (prefers-reduced-motion: no-preference) {
  .root:not([data-reduced]) .part { transition: opacity var(--mk-duration-base, 240ms) var(--mk-ease-standard, ease), transform var(--pop-dur, 600ms) var(--pop, ease); }
  .root:not([data-reduced]) .part[data-on='false'] { transition: opacity var(--mk-duration-fast, 160ms) var(--mk-ease-exit, ease), transform var(--mk-duration-fast, 160ms) var(--mk-ease-exit, ease); }
  .root:not([data-reduced]) .paint { transition: stroke var(--mk-duration-base, 240ms) var(--mk-ease-standard, ease); }
  .root:not([data-reduced]) .paintFill { transition: fill var(--mk-duration-base, 240ms) var(--mk-ease-standard, ease); }
}

/* HTML dimension labels laid over the drawing */
.dims { position: absolute; inset: 0; pointer-events: none; }
.dimLabel {
  position: absolute;
  transform: translate(0, -50%);
  padding: 1px 4px;
  font-family: var(--mk-font-mono, ui-monospace, monospace);
  font-size: 0.75rem;
  line-height: 1.2;
  letter-spacing: 0.04em;
  text-transform: uppercase;
  white-space: nowrap;
  color: var(--mk-signal, #bf2f09);
  background: var(--mk-surface, #fbf9f4);
  font-variant-numeric: tabular-nums;
}
.dimLabel[data-align='center'] { transform: translate(-50%, -50%); }
.dimLabel b { font-weight: 700; }

/* Total strip under the drawing */
.strip { display: flex; align-items: center; justify-content: space-between; gap: 12px; padding-top: 10px; }
.total { display: flex; align-items: baseline; gap: 10px; margin: 0; }
.totalLabel { font-family: var(--mk-font-mono, ui-monospace, monospace); font-size: 0.75rem; letter-spacing: 0.08em; text-transform: uppercase; color: var(--mk-ink-muted, #5c5a52); }
.totalValue { font-family: var(--mk-font-display, ui-sans-serif, system-ui, sans-serif); font-size: 1.625rem; font-weight: 700; letter-spacing: -0.02em; }
@container (min-width: 960px) {
  .strip { padding-top: 18px; margin-top: 18px; border-top: 1px solid var(--mk-line, #11110f24); }
  .totalValue { font-size: 2.25rem; }
}

/* Odometer */
.ticker { display: inline-flex; }
.tickRow { display: inline-flex; font-variant-numeric: tabular-nums; }
.tickDigit { display: inline-block; height: 1.1em; line-height: 1.1em; overflow: hidden; }
.tickStrip { display: flex; flex-direction: column; }
.tickCell { display: block; height: 1.1em; width: 0.62em; text-align: center; }
.tickSymbol { display: inline-block; height: 1.1em; line-height: 1.1em; }

/* ── Buttons ───────────────────────────────────────────────────────────── */
.primary, .secondary {
  display: inline-flex; align-items: center; justify-content: center; gap: 8px;
  min-height: 48px; padding: 0 20px; border-radius: var(--mk-radius-s, 4px);
  font: 600 0.9375rem/1 var(--mk-font-text, ui-sans-serif, system-ui, sans-serif);
  cursor: pointer; transition: background-color var(--mk-duration-fast, 160ms) var(--mk-ease-standard, ease), transform var(--mk-duration-instant, 90ms);
}
.primary { border: 0; background: var(--mk-signal, #bf2f09); color: var(--mk-on-signal, #fff); }
.primary:hover { background: color-mix(in oklab, var(--mk-signal, #bf2f09) 86%, #000); }
.secondary { border: 1px solid var(--mk-line-strong, #11110f); background: transparent; color: var(--mk-ink, #11110f); }
.secondary:hover { background: var(--mk-surface-2, #e9e5da); }
.primary:active, .secondary:active { transform: translateY(1px) scale(0.99); }
.primary:focus-visible, .secondary:focus-visible, .textBtn:focus-visible, .compareLink:focus-visible { outline: 2px solid var(--mk-focus, #1d4ed8); outline-offset: 3px; }
.textBtn {
  min-height: 32px; padding: 4px 2px; border: 0; background: none; color: var(--mk-ink, #11110f); cursor: pointer;
  font: 500 0.875rem/1.3 var(--mk-font-text, ui-sans-serif, system-ui, sans-serif);
  text-decoration: underline; text-underline-offset: 3px; text-decoration-thickness: 1px; text-align: left;
}
.textBtn:hover { text-decoration-thickness: 2px; }

/* ── Options ───────────────────────────────────────────────────────────── */
.group { margin: 0; padding: 22px 0 26px; border: 0; border-top: 1px solid var(--mk-line, #11110f24); min-inline-size: 0; }
.legend {
  display: flex; align-items: baseline; gap: 10px; padding: 0; float: left; width: 100%;
  font-family: var(--mk-font-display, ui-sans-serif, system-ui, sans-serif); font-weight: 650; font-size: 1.1875rem; letter-spacing: -0.015em;
}
.legend + * { clear: both; }
.num { font-family: var(--mk-font-mono, ui-monospace, monospace); font-size: 0.75rem; font-weight: 400; letter-spacing: 0.04em; color: var(--mk-signal, #bf2f09); }
.hint { margin: 8px 0 0; padding-top: 4px; max-width: 52ch; font-size: 0.875rem; line-height: 1.45; color: var(--mk-ink-muted, #5c5a52); }
.choices { display: grid; gap: 8px; margin-top: 14px; grid-template-columns: repeat(auto-fill, minmax(min(100%, 9.75rem), 1fr)); }
.choices[data-kind='size'] { grid-template-columns: repeat(4, minmax(0, 1fr)); }
.choices[data-kind='frame'] { grid-template-columns: repeat(auto-fill, minmax(min(100%, 13rem), 1fr)); }
.choices[data-kind='paint'] { grid-template-columns: repeat(2, minmax(0, 1fr)); }

.choice, .extra {
  position: relative;
  display: grid;
  align-content: start;
  gap: 3px;
  min-height: 48px;
  padding: 12px 12px 11px;
  border: 1px solid var(--mk-line, #11110f24);
  border-radius: var(--mk-radius-s, 4px);
  background: var(--mk-surface, #fbf9f4);
  cursor: pointer;
  transition: background-color var(--mk-duration-fast, 160ms) var(--mk-ease-standard, ease), border-color var(--mk-duration-fast, 160ms);
}
.choice:hover, .extra:hover { background: var(--mk-surface-2, #e9e5da); }
.choice:has(:checked), .extra:has(:checked) { border-color: var(--mk-ink, #11110f); box-shadow: inset 0 0 0 1px var(--mk-ink, #11110f); }
.choice:has(:focus-visible), .extra:has(:focus-visible) { outline: 2px solid var(--mk-focus, #1d4ed8); outline-offset: 2px; }
.input {
  position: absolute; inset: 0; width: 100%; height: 100%; margin: 0; opacity: 0; cursor: pointer;
  scroll-margin-top: calc(44px + var(--plate-h) + 12px);
  scroll-margin-bottom: 24px;
}
@container (min-width: 960px) { .input { scroll-margin-top: 64px; } }

/* selection mark: ring when free, filled when chosen */
.choice::after {
  content: ''; position: absolute; top: 12px; right: 12px; width: 10px; height: 10px; border-radius: 50%;
  border: 1.5px solid var(--mk-ink-muted, #5c5a52);
}
.choice:has(:checked)::after { background: var(--mk-ink, #11110f); border-color: var(--mk-ink, #11110f); box-shadow: inset 0 0 0 2px var(--mk-surface, #fbf9f4); }

.name { font-weight: 600; font-size: 0.9375rem; line-height: 1.25; padding-right: 18px; }
.note { font-size: 0.8125rem; line-height: 1.35; color: var(--mk-ink-muted, #5c5a52); }
.delta { margin-top: 6px; font-family: var(--mk-font-mono, ui-monospace, monospace); font-size: 0.75rem; letter-spacing: 0.02em; font-variant-numeric: tabular-nums; color: var(--mk-ink, #11110f); }

.sizeNum { font-family: var(--mk-font-display, ui-sans-serif, system-ui, sans-serif); font-weight: 700; font-size: 1.625rem; line-height: 1; letter-spacing: -0.03em; }
.choices[data-kind='size'] .choice { padding-inline: 10px; }
.choices[data-kind='size'] .note { font-size: 0.75rem; }

.paintRow { display: flex; align-items: center; gap: 10px; }
.paintText { display: grid; gap: 2px; }
.swatch { flex: none; width: 28px; height: 28px; border-radius: 50%; box-shadow: inset 0 0 0 1px color-mix(in oklab, var(--mk-ink, #11110f) 35%, transparent); }

.barIcon { width: 76px; height: 38px; margin: -2px 0 4px -4px; overflow: visible; }
.icStem { fill: none; stroke: var(--hc-metal); stroke-linecap: round; }
.icOutline { fill: none; stroke: var(--hc-line); stroke-linecap: round; stroke-linejoin: round; }
.icTape { fill: none; stroke: var(--hc-rubber); stroke-linecap: round; stroke-linejoin: round; }
.icMetal { fill: none; stroke: var(--hc-metal); stroke-linecap: round; stroke-linejoin: round; }

.geo { display: flex; flex-wrap: wrap; margin: 16px 0 0; border: 1px solid var(--mk-line, #11110f24); border-width: 1px 1px 0 0; }
.geo > div { flex: 1 1 5.6rem; padding: 8px 10px; border: solid var(--mk-line, #11110f24); border-width: 0 0 1px 1px; }
.geo dt { font-family: var(--mk-font-mono, ui-monospace, monospace); font-size: 0.6875rem; letter-spacing: 0.06em; text-transform: uppercase; color: var(--mk-ink-muted, #5c5a52); }
.geo dd { margin: 2px 0 0; font-family: var(--mk-font-mono, ui-monospace, monospace); font-size: 0.9375rem; font-variant-numeric: tabular-nums; }

.notice, .blockedNote {
  display: flex; flex-wrap: wrap; align-items: baseline; gap: 4px 12px; margin: 12px 0 0; padding: 10px 12px;
  border-left: 2px solid var(--mk-signal, #bf2f09); background: var(--mk-surface, #fbf9f4); font-size: 0.875rem; line-height: 1.4;
}
.blockedNote { margin-top: 8px; }

.extras { display: grid; gap: 8px; margin-top: 14px; }
.extraItem { display: grid; }
.extra { grid-template-columns: auto minmax(0, 1fr) auto; align-items: center; gap: 12px; }
.extra .delta { margin: 0; }
.extraText { display: grid; gap: 2px; }
.box {
  display: grid; place-items: center; width: 22px; height: 22px; border-radius: 3px;
  border: 1.5px solid var(--mk-ink-muted, #5c5a52); background: var(--mk-surface, #fbf9f4);
}
.box svg { width: 16px; height: 16px; fill: none; stroke: var(--mk-bg, #f3f0e8); stroke-width: 2.2; stroke-linecap: round; stroke-linejoin: round; opacity: 0; }
.extra:has(:checked) .box { background: var(--mk-ink, #11110f); border-color: var(--mk-ink, #11110f); }
.extra:has(:checked) .box svg { opacity: 1; }
.extra[data-blocked] { border-style: dashed; cursor: not-allowed; background: transparent; }
.extra[data-blocked] .input { cursor: not-allowed; }
.extra[data-blocked] .name { text-decoration: line-through; text-decoration-thickness: 1px; }

/* ── Ticket (summary) ──────────────────────────────────────────────────── */
.ticket {
  margin-top: 8px;
  padding: 22px 20px 20px;
  background: var(--mk-surface, #fbf9f4);
  border: 1px solid var(--mk-line, #11110f24);
  border-radius: var(--mk-radius-m, 10px);
  scroll-margin-top: calc(44px + var(--plate-h) + 12px);
}
@container (min-width: 960px) { .ticket { scroll-margin-top: 64px; } }
.ticketHead { display: flex; justify-content: space-between; align-items: baseline; gap: 12px; padding-bottom: 14px; border-bottom: 1px dashed var(--mk-line-strong, #11110f); }
.ticketTitle { margin: 0; font-family: var(--mk-font-display, ui-sans-serif, system-ui, sans-serif); font-size: 1.375rem; font-weight: 700; letter-spacing: -0.02em; }
.ticketTitle:focus-visible { outline: 2px solid var(--mk-focus, #1d4ed8); outline-offset: 4px; }
.lines { margin: 0; }
.line { display: grid; grid-template-columns: minmax(6.5rem, auto) minmax(0, 1fr) auto; gap: 4px 14px; align-items: baseline; padding: 10px 0; border-bottom: 1px solid var(--mk-line, #11110f24); }
.line dt { font-family: var(--mk-font-mono, ui-monospace, monospace); font-size: 0.6875rem; letter-spacing: 0.06em; text-transform: uppercase; color: var(--mk-ink-muted, #5c5a52); }
.line dd { margin: 0; font-size: 0.9375rem; }
.linePrice { font-family: var(--mk-font-mono, ui-monospace, monospace); font-size: 0.8125rem !important; font-variant-numeric: tabular-nums; text-align: right; }
.ticketTotal { display: flex; justify-content: space-between; align-items: baseline; margin: 16px 0 0; font-family: var(--mk-font-display, ui-sans-serif, system-ui, sans-serif); font-weight: 700; font-size: 1.125rem; }
.ticketSum { font-size: 2rem; letter-spacing: -0.02em; font-variant-numeric: tabular-nums; }
.terms { margin: 6px 0 0; font-size: 0.8125rem; line-height: 1.45; color: var(--mk-ink-muted, #5c5a52); }
.actions { display: grid; gap: 8px; margin-top: 18px; justify-items: stretch; }
.actions .textBtn { justify-self: start; margin-top: 4px; }
.feedback:empty { display: none; }
.sent { margin: 14px 0 0; padding: 10px 12px; border-left: 2px solid var(--mk-ink, #11110f); font-size: 0.875rem; line-height: 1.45; background: var(--mk-bg, #f3f0e8); }
.manual { display: grid; gap: 6px; margin: 14px 0 0; font-size: 0.875rem; }
.linkField { min-height: 40px; padding: 8px 10px; border: 1px solid var(--mk-line-strong, #11110f); border-radius: var(--mk-radius-s, 4px); background: var(--mk-bg, #f3f0e8); color: var(--mk-ink, #11110f); font: 0.8125rem/1.3 var(--mk-font-mono, ui-monospace, monospace); }

/* ── Why a drawing ─────────────────────────────────────────────────────── */
.why {
  display: grid; gap: 36px;
  max-width: 1520px; margin: 0 auto;
  padding: clamp(56px, 9cqi, 120px) 16px clamp(48px, 7cqi, 96px);
  border-top: 1px solid var(--mk-line-strong, #11110f);
}
.kicker { margin: 0 0 14px; font-family: var(--mk-font-mono, ui-monospace, monospace); font-size: 0.75rem; letter-spacing: 0.1em; text-transform: uppercase; color: var(--mk-signal, #bf2f09); }
.whyTitle { margin: 0; max-width: 13ch; font-family: var(--mk-font-display, ui-sans-serif, system-ui, sans-serif); font-weight: 750; font-size: clamp(2.125rem, 1.1rem + 4.2cqi, 4rem); line-height: 0.98; letter-spacing: -0.04em; text-wrap: balance; }
.reasons { list-style: none; margin: 0; padding: 0; display: grid; }
.reasons li { display: grid; grid-template-columns: 3rem minmax(0, 1fr); column-gap: 12px; padding: 18px 0 20px; border-top: 1px solid var(--mk-line, #11110f24); }
.reasons li:last-child { border-bottom: 1px solid var(--mk-line, #11110f24); }
.reasons h3 { grid-column: 2; margin: 0; font-family: var(--mk-font-display, ui-sans-serif, system-ui, sans-serif); font-size: 1.25rem; font-weight: 650; letter-spacing: -0.015em; }
.reasons p { grid-column: 2; margin: 8px 0 0; max-width: 60ch; font-size: 0.9375rem; line-height: 1.55; color: var(--mk-ink-muted, #5c5a52); text-wrap: pretty; }
.reasonNum { grid-row: span 2; padding-top: 4px; font-family: var(--mk-font-mono, ui-monospace, monospace); font-size: 0.8125rem; color: var(--mk-signal, #bf2f09); }
.compare { display: grid; gap: 14px; padding: 20px; border: 1px solid var(--mk-line-strong, #11110f); border-radius: var(--mk-radius-s, 4px); align-content: start; }
.compare p { margin: 0; font-size: 0.9375rem; line-height: 1.5; max-width: 62ch; }
.compareLink {
  justify-self: start; display: inline-flex; align-items: center; min-height: 44px; font-weight: 600; color: var(--mk-ink, #11110f);
  text-decoration: underline; text-underline-offset: 4px; text-decoration-thickness: 1px;
}
.compareLink:hover { text-decoration-thickness: 2px; }
@container (min-width: 960px) {
  .why { grid-template-columns: minmax(0, 5fr) minmax(0, 7fr); column-gap: clamp(28px, 4cqi, 72px); padding-inline: 32px; }
  .whyHead { grid-row: span 2; }
}

.colophon { max-width: 1520px; margin: 0 auto; padding: 20px 16px 40px; border-top: 1px solid var(--mk-line, #11110f24); }
.colophon p { margin: 0; font-size: 0.8125rem; color: var(--mk-ink-muted, #5c5a52); }
@container (min-width: 960px) { .colophon { padding-inline: 32px; } }

/* ── The drawing answers the hand ──────────────────────────────────────── */
/* Parts light up and lift under the pointer; the option card for the same part does the same from the side. */
.hit { cursor: pointer; transition: transform var(--pop-dur, 600ms) var(--pop, ease), filter var(--mk-duration-fast, 160ms) var(--mk-ease-standard, ease); }
.hit[data-hover] { transform: translateY(-12px); filter: drop-shadow(0 16px 9px rgb(20 18 12 / 0.22)); }
.hit[data-hover] .outline, .hit[data-hover] .edge, .hit[data-hover] .saddle, .hit[data-hover] .lamp { stroke: var(--mk-signal, #bf2f09); }
.hit[data-hover] .outlineFill { fill: var(--mk-signal, #bf2f09); }
.wheel { cursor: grab; touch-action: pan-y; }
.spin { cursor: grab; touch-action: none; }
.wheel:active, .spin:active { cursor: grabbing; }
.valve { fill: var(--hc-metal); stroke: var(--hc-line); stroke-width: 1; vector-effect: non-scaling-stroke; }
.flow path { fill: none; stroke-linecap: round; stroke-dasharray: 1; stroke-dashoffset: 1; }
/* Dynamo light: brightness follows the front wheel's speed (a faint standlight when still). */
.beam { pointer-events: none; opacity: calc(0.08 + var(--dynamo, 0) * 0.92); }
.partTag {
  position: absolute; z-index: 2; top: 12px; right: 12px; max-width: calc(100% - 24px); overflow: hidden; text-overflow: ellipsis; padding: 5px 9px; border-radius: 999px; white-space: nowrap; pointer-events: none;
  background: var(--mk-ink, #11110f); color: var(--mk-bg, #f3f0e8); font: 600 0.6875rem/1.2 var(--mk-font-mono, ui-monospace, monospace); letter-spacing: 0.03em;
  box-shadow: 0 1px 2px rgb(0 0 0 / 0.25), 0 10px 20px -10px rgb(0 0 0 / 0.5);
  animation: hc-tag var(--settle-dur, 490ms) var(--settle, ease) both;
}
@keyframes hc-tag { from { opacity: 0; translate: 0 8px; } }
/* The twins sit in the drawing's free top-left corner: icons on narrow plates (their names stay accessible), labelled on wide ones. */
.spinBar { position: absolute; z-index: 2; top: 8px; left: 8px; display: flex; gap: 6px; }
.spinLabel { position: absolute; width: 1px; height: 1px; margin: -1px; padding: 0; overflow: hidden; clip: rect(0 0 0 0); white-space: nowrap; border: 0; }
@container (min-width: 960px) {
  .spinBar { top: 12px; left: 12px; flex-direction: column; align-items: flex-start; }
  .spinLabel { position: static; width: auto; height: auto; margin: 0; overflow: visible; clip: auto; }
}
.spinBtn {
  display: inline-flex; align-items: center; justify-content: center; gap: 7px; min-width: 36px; min-height: 36px; padding: 0 9px; border: 1px solid var(--mk-line-strong, #11110f); border-radius: 999px;
  background: var(--mk-surface, #fbf9f4); color: var(--mk-ink, #11110f); font: 500 0.75rem/1 var(--mk-font-mono, ui-monospace, monospace); letter-spacing: 0.02em;
  cursor: pointer; user-select: none; -webkit-user-select: none; touch-action: manipulation; box-shadow: var(--sh-rest);
  transition: transform var(--press-dur, 330ms) var(--press, ease), box-shadow var(--press-dur, 330ms) var(--press, ease);
}
.spinBtn:hover { transform: translateY(-1px); box-shadow: var(--sh-lift); }
@container (min-width: 960px) { .spinBtn { padding: 0 12px 0 9px; } }
.spinBtn:active { transform: translateY(1px) scale(0.97); box-shadow: var(--sh-press); transition-duration: var(--mk-duration-instant, 90ms); }
.spinBtn:focus-visible { outline: 2px solid var(--mk-focus, #1d4ed8); outline-offset: 2px; }
.spinBtn svg { width: 16px; height: 16px; fill: none; stroke: currentColor; stroke-width: 1.5; stroke-linecap: round; stroke-linejoin: round; }

/* ── Option cards: lift under the pointer, press in, the chosen one sits down ── */
.choice, .extra { box-shadow: var(--sh-rest); transition: transform var(--press-dur, 330ms) var(--press, ease), box-shadow var(--press-dur, 330ms) var(--press, ease), background-color var(--mk-duration-fast, 160ms), border-color var(--mk-duration-fast, 160ms); }
.choice:hover, .extra:hover:not([data-blocked]) { transform: translateY(-2px); box-shadow: var(--sh-lift); background: var(--mk-surface, #fbf9f4); }
.choice:active, .extra:active:not([data-blocked]) { transform: translateY(1px) scale(0.985); box-shadow: var(--sh-press); transition-duration: var(--mk-duration-instant, 90ms); transition-timing-function: var(--mk-ease-standard, ease); }
.choice:has(:checked), .extra:has(:checked) { box-shadow: inset 0 0 0 1px var(--mk-ink, #11110f), var(--sh-press); }
.choice:has(:checked):hover, .extra:has(:checked):hover { box-shadow: inset 0 0 0 1px var(--mk-ink, #11110f), var(--sh-rest); }
.choice::after { transition: background-color var(--mk-duration-fast, 160ms), box-shadow var(--pop-dur, 600ms) var(--pop, ease), transform var(--pop-dur, 600ms) var(--pop, ease); }
.choice:has(:checked)::after { transform: scale(1.15); }
.extra[data-blocked] { box-shadow: none; }
.primary, .secondary { transition: transform var(--press-dur, 330ms) var(--press, ease), box-shadow var(--press-dur, 330ms) var(--press, ease), background-color var(--mk-duration-fast, 160ms); }
.primary { box-shadow: inset 0 1px 0 rgb(255 255 255 / 0.2), 0 1px 1.5px rgb(0 0 0 / 0.22), 0 8px 18px -9px color-mix(in oklab, var(--mk-signal, #bf2f09) 75%, #000); }
.primary:hover { transform: translateY(-2px); box-shadow: inset 0 1px 0 rgb(255 255 255 / 0.2), 0 1px 1px rgb(0 0 0 / 0.14), 0 16px 26px -12px color-mix(in oklab, var(--mk-signal, #bf2f09) 80%, #000); }
.secondary { box-shadow: var(--sh-rest); }
.secondary:hover { transform: translateY(-2px); box-shadow: var(--sh-lift); }
.primary:active, .secondary:active { transform: translateY(1px) scale(0.98); box-shadow: var(--sh-press); transition-duration: var(--mk-duration-instant, 90ms); }

/* ── Reduced motion: no lift, drop or spring; parts and paint change in place ── */
.root[data-reduced] .hit, .root[data-reduced] .choice, .root[data-reduced] .extra, .root[data-reduced] .spinBtn, .root[data-reduced] .primary,
.root[data-reduced] .secondary, .root[data-reduced] .choice::after { transition: none; }
.root[data-reduced] .hit[data-hover] { transform: none; filter: none; }
.root[data-reduced] .choice:hover, .root[data-reduced] .extra:hover, .root[data-reduced] .spinBtn:hover, .root[data-reduced] .primary:hover, .root[data-reduced] .secondary:hover { transform: none; }
.root[data-reduced] .partTag { animation: none; }
@media (prefers-reduced-motion: reduce) {
  .hit, .choice, .extra, .spinBtn, .primary, .secondary { transition: none; }
}

'use client';
/**
 * Odometer figure — the number-ticker recipe's rolling digit columns (effects/number-ticker), reworked to take any
 * value (the recipe itself only plays its own preset series). The rolling digits are aria-hidden; the formatted value
 * is a single text node for assistive technology.
 */
import { useEffect, useRef, useState } from 'react';
import { cssEase, duration as D, useIsomorphicLayoutEffect } from '../../../motion';
import styles from './styles.module.css';

function Digit({ digit, dir, delay, reduced }: { digit: number; dir: 1 | -1; delay: number; reduced: boolean }) {
  const [roll, setRoll] = useState<{ strip: number[]; dir: 1 | -1; id: number }>({ strip: [digit], dir: 1, id: 0 });
  const shown = useRef(digit);
  const strip = useRef<HTMLSpanElement>(null);

  useIsomorphicLayoutEffect(() => {
    const from = shown.current;
    if (from === digit) return;
    shown.current = digit;
    if (reduced) { setRoll((r) => ({ strip: [digit], dir: 1, id: r.id + 1 })); return; }
    const seq = [from];
    for (let d = from; d !== digit;) { d = (d + (dir > 0 ? 1 : 9)) % 10; seq.push(d); }
    setRoll((r) => ({ strip: dir > 0 ? seq : seq.reverse(), dir, id: r.id + 1 }));
  }, [digit, dir, reduced]);

  useIsomorphicLayoutEffect(() => {
    const el = strip.current;
    const steps = roll.strip.length - 1;
    if (!el || steps < 1 || typeof el.animate !== 'function') return;
    const far = `translateY(${(-steps / (steps + 1)) * 100}%)`;
    const a = el.animate({ transform: roll.dir > 0 ? ['translateY(0)', far] : [far, 'translateY(0)'] }, { duration: D.moderate + steps * 20, delay, easing: cssEase('emphasized'), fill: 'both' });
    const id = roll.id;
    a.finished.then(() => setRoll((r) => (r.id === id ? { strip: [shown.current], dir: 1, id: r.id + 1 } : r)), () => {});
    return () => a.cancel();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [roll.id]);

  return (
    <span className={styles.tickDigit}>
      <span ref={strip} className={styles.tickStrip}>{roll.strip.map((d, i) => <span key={i} className={styles.tickCell}>{d}</span>)}</span>
    </span>
  );
}

export function Ticker({ value, format, reduced, className }: { value: number; format: (n: number) => string; reduced: boolean; className?: string }) {
  // Direction of travel: compared with the value committed last time (the ref updates after commit).
  const prev = useRef(value);
  useEffect(() => { prev.current = value; }, [value]);

  const text = format(value);
  const chars = Array.from(text);
  let order = 0;
  const cells = chars.map((ch, k) => ({ ch, fromRight: chars.length - 1 - k }));
  const delays = new Map<number, number>();
  for (let k = cells.length - 1; k >= 0; k--) if (/\d/.test(cells[k].ch)) delays.set(cells[k].fromRight, order++ * 28);
  const liveDir: 1 | -1 = value < prev.current ? -1 : 1;

  return (
    <span className={`${styles.ticker} ${className ?? ''}`}>
      <span className={styles.srOnly}>{text}</span>
      <span aria-hidden="true" className={styles.tickRow}>
        {cells.map((c) => /\d/.test(c.ch)
          ? <Digit key={`${c.fromRight}d`} digit={Number(c.ch)} dir={liveDir} delay={delays.get(c.fromRight) ?? 0} reduced={reduced} />
          : <span key={`${c.fromRight}s${c.ch}`} className={styles.tickSymbol}>{c.ch}</span>)}
      </span>
    </span>
  );
}
